def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/noaa_wildfires_variabledescrip.csv'
    # Try common Windows-1252/Latin-1 encodings used in NOAA documentation exports
    try:
        return pd.read_csv(path, encoding='cp1252')
    except UnicodeDecodeError:
        return pd.read_csv(path, encoding='latin1')
